-- Auth identities remain in Supabase auth.users; this schema never stores passwords.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;

create table public.regions(id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.counties(id uuid primary key default gen_random_uuid(), region_id uuid not null references public.regions(id), code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,region_id));
create index counties_region_idx on public.counties(region_id);
create table public.sub_counties(id uuid primary key default gen_random_uuid(), county_id uuid not null references public.counties(id), code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,county_id));
create index sub_counties_county_idx on public.sub_counties(county_id);
create table public.branches(id uuid primary key default gen_random_uuid(), county_id uuid not null references public.counties(id), sub_county_id uuid not null, code text not null unique, name text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(sub_county_id,county_id) references public.sub_counties(id,county_id), unique(id,county_id,sub_county_id));
create table public.departments(id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.membership_categories(id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, description text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create table public.user_profiles(user_id uuid primary key references auth.users(id) on delete cascade, email_address text, display_name text, phone_number text, account_status text not null default 'PENDING_VERIFICATION' check(account_status in ('PENDING_VERIFICATION','ACTIVE','SUSPENDED','CLOSED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.roles(role_key text primary key, display_name text not null, privileged boolean not null default false, active boolean not null default true);
create table public.permissions(permission_key text primary key, description text not null);
create table public.role_permissions(role_key text not null references public.roles(role_key), permission_key text not null references public.permissions(permission_key), primary key(role_key,permission_key));
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade, role_key text not null references public.roles(role_key), active boolean not null default true, assigned_by uuid references auth.users(id), assigned_at timestamptz not null default now(), primary key(user_id,role_key));
create table public.administrative_assignments(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), role_key text not null references public.roles(role_key), scope_level text not null check(scope_level in ('GLOBAL','REGION','COUNTY','SUB_COUNTY','BRANCH')), region_id uuid references public.regions(id), county_id uuid references public.counties(id), sub_county_id uuid references public.sub_counties(id), branch_id uuid references public.branches(id), active boolean not null default true, assigned_by uuid not null references auth.users(id), assigned_at timestamptz not null default now(), expires_at timestamptz, check((scope_level='GLOBAL' and region_id is null and county_id is null and sub_county_id is null and branch_id is null) or (scope_level='REGION' and region_id is not null and county_id is null and sub_county_id is null and branch_id is null) or (scope_level='COUNTY' and region_id is null and county_id is not null and sub_county_id is null and branch_id is null) or (scope_level='SUB_COUNTY' and region_id is null and county_id is null and sub_county_id is not null and branch_id is null) or (scope_level='BRANCH' and region_id is null and county_id is null and sub_county_id is null and branch_id is not null)));
create index admin_assignments_user_idx on public.administrative_assignments(user_id,role_key) where active;

create table public.membership_applications(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), full_legal_name text not null, date_of_birth date not null check(date_of_birth<current_date), gender text, phone_number text not null, email_address text not null, county_id uuid not null references public.counties(id), sub_county_id uuid not null, physical_address text not null, occupation text not null, next_of_kin_name text not null, next_of_kin_phone text not null, category_id uuid references public.membership_categories(id), status text not null default 'SUBMITTED' check(status in ('SUBMITTED','PAYMENT_PENDING','UNDER_REVIEW','MORE_INFORMATION_REQUIRED','APPROVED','REJECTED')), registration_fee_kes numeric(12,2) not null default 300 check(registration_fee_kes=300), registration_payment_status text not null default 'UNPAID' check(registration_payment_status in ('UNPAID','PENDING','VERIFIED','FAILED','REFUNDED')), terms_accepted boolean not null default false, privacy_accepted boolean not null default false, terms_version text not null default 'draft-2026-01', privacy_version text not null default 'draft-2026-01', consented_at timestamptz not null, reviewed_by uuid references auth.users(id), reviewed_at timestamptz, decision_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(sub_county_id,county_id) references public.sub_counties(id,county_id));
create index applications_owner_idx on public.membership_applications(user_id,created_at desc);
create index applications_queue_idx on public.membership_applications(status,county_id,created_at);
alter table public.membership_applications add constraint application_name_length check(length(trim(full_legal_name)) between 2 and 160);
alter table public.membership_applications add constraint application_email_length check(length(email_address)<=254 and email_address ~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$');
alter table public.membership_applications add constraint application_phone_format check(phone_number ~ '^[+]?[0-9 ()-]{9,20}$' and next_of_kin_phone ~ '^[+]?[0-9 ()-]{9,20}$');
alter table public.membership_applications add constraint application_text_lengths check(length(physical_address)<=240 and length(occupation)<=120 and length(next_of_kin_name) between 2 and 160);
create unique index membership_app_one_open_idx on public.membership_applications(user_id) where status <> 'REJECTED';
create table public.members(id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id), application_id uuid not null unique references public.membership_applications(id), membership_number text not null unique, category_id uuid references public.membership_categories(id), county_id uuid not null references public.counties(id), sub_county_id uuid not null, branch_id uuid, status text not null default 'ACTIVE' check(status in ('ACTIVE','SUSPENDED','INACTIVE','CLOSED')), approved_by uuid not null references auth.users(id), approved_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(sub_county_id,county_id) references public.sub_counties(id,county_id), foreign key(branch_id,county_id,sub_county_id) references public.branches(id,county_id,sub_county_id));
create index members_jurisdiction_idx on public.members(county_id,sub_county_id,branch_id);
create table public.employee_profiles(user_id uuid primary key references auth.users(id), employee_number text not null unique, department_id uuid references public.departments(id), county_id uuid references public.counties(id), branch_id uuid references public.branches(id), employment_status text not null default 'ACTIVE' check(employment_status in ('ACTIVE','SUSPENDED','ENDED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());

