create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.user_profiles(user_id,email_address,account_status) values(new.id,lower(new.email),case when new.email_confirmed_at is not null then 'ACTIVE' else 'PENDING_VERIFICATION' end) on conflict(user_id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_auth_user();
create or replace function public.handle_auth_user_updated() returns trigger language plpgsql security definer set search_path='' as $$
begin
 update public.user_profiles set email_address=lower(new.email), account_status=case
   when account_status='PENDING_VERIFICATION' and new.email_confirmed_at is not null then 'ACTIVE'
   else account_status end
 where user_id=new.id;
 return new;
end; $$;
create trigger on_auth_user_updated after update of email,email_confirmed_at on auth.users for each row execute function public.handle_auth_user_updated();
do $$ declare t text; begin foreach t in array array['regions','counties','sub_counties','branches','departments','membership_categories','user_profiles','membership_applications','members','employee_profiles'] loop execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop; end $$;
